    public static IReadOnlyCollection<string> CardIds => CardTable.Keys;

    public static IReadOnlyCollection<string> PowerIds => PowerTable.Keys;

    public static bool CardPlaysRecordRisk(string nativeId)
        => CardTable.TryGetValue(nativeId, out bool value)
            ? value
            : throw new UnsupportedImportException(ImportReason.MissingMirrorRisk,
                $"卡牌 {nativeId} 不在镜像覆盖率表中");

    public static bool PowerRecordsDeathHistoryRisk(string nativeId)
        => PowerTable.TryGetValue(nativeId, out bool value)
            ? value
            : throw new UnsupportedImportException(ImportReason.MissingMirrorRisk,
                $"Power {nativeId} 不在镜像覆盖率表中");
}
